head.b:skin:
/*
-----------------------------------------------
Theme Name			: Cultura Pocket (custom)
Base Theme			: Daybreak 2.2
Redesign			: card layout inspired by Estante Diagonal
----------------------------------------------- */
/* Variable definitions
   ====================
   <Variable name="keycolor" description="Main Color" type="color" default="#f0ece8" value="#fce8b2"/>
   <Group description="Blog Color" selector="body">
     <Variable name="main.color" description="Color Accent" type="color" default="#f0ece8" value="#F7CB4D"/>
   </Group>
*/

/* ------------- RESET ------------- */
a,abbr,acronym,address,applet,article,aside,audio,b,big,blockquote,body,canvas,caption,center,cite,code,dd,del,details,dfn,div,dl,dt,em,embed,fieldset,figcaption,figure,footer,form,h1,h2,h3,h4,h5,h6,header,hgroup,html,i,iframe,img,ins,kbd,label,legend,li,mark,menu,nav,object,ol,output,p,pre,q,ruby,s,samp,section,small,span,strike,strong,sub,summary,sup,table,tbody,td,tfoot,th,thead,time,tr,tt,u,ul,var,video{margin:0;padding:0;border:0;font:inherit;vertical-align:baseline}article,aside,details,figcaption,figure,footer,header,hgroup,menu,nav,section{display:block}body{line-height:1}ol,ul{list-style:none}blockquote,q{quotes:none}blockquote:after,blockquote:before,q:after,q:before{content:'';content:none}table{border-collapse:collapse;border-spacing:0}.clear{clear:both}
*{box-sizing:border-box}

/* ------------- BACKEND ------------- */
body#layout #topmenuwrap {height: auto; position: relative; width: 90%;}
body#layout #topmenuwrap .topwrap {width: auto;}
body#layout #topmenuwrap #TOP-MENU, body#layout #topmenuwrap #SOCIAL-MEDIA {width: 44%; float:left}
body#layout #TOP-MENU .widget {width: 100%}
body#layout #TOP-MENU .Label .widget-content, body#layout #TOP-MENU .LinkList .widget-content {display: block}
body#layout #TOP-MENU .Label .widget-content, body#layout #TOP-MENU .LinkList .widget-content {
    position: relative;
    background: #f6f6f6;
    padding: 16px;
}
body#layout div.section {height: auto}
body#layout #TOP-MENU {visibility: visible;}
#layout #featwrap {width:100%}
#layout .blog-wrap {width: 62%; margin:0}

/* ------------- DESIGN TOKENS ------------- */
:root{
	--cp-yellow:#F7CB4D;
	--cp-pink:#FF7A9C;
	--cp-red:#FF5A5F;
	--cp-blue:#4DA9F7;
	--cp-green:#3FC28A;
	--cp-ink:#221E1B;
	--cp-muted:#767068;
	--cp-paper:#FFFCF6;
	--cp-card:#FFFFFF;
	--cp-line:#EFE7DA;
	--cp-radius:16px;
	--cp-shadow:0 10px 30px rgba(34,30,27,0.08);
}

/* ------------- LAYOUT ------------- */
body {
	background-color: var(--cp-paper);
	font-family: 'Poppins', 'Libre Baskerville', serif;
	font-size: 13px;
	line-height: 1.9em;
	color: var(--cp-ink);
}
a:link { text-decoration:none; color: var(--cp-ink); }
a:visited { text-decoration:none; color: var(--cp-ink); }
a:hover { text-decoration:none; color: var(--cp-red); }

/* rainbow top strip, like the moodboard site */
body:before{
	content:"";
	display:block;
	height:6px;
	width:100%;
	position:fixed;
	top:0; left:0; z-index:1001;
	background:linear-gradient(90deg, var(--cp-red) 0 20%, var(--cp-blue) 20% 40%, var(--cp-green) 40% 60%, var(--cp-yellow) 60% 80%, var(--cp-pink) 80% 100%);
}

.container {
    margin: 45px auto;
    max-width: 1140px;
    width: 100%;
}
.content-inner {padding:0}
.blog-wrap {
	width: 700px; margin: 0 40px 0 0; padding:0; float: left; display: inline-block;
}
.sidebar-wrap {
	width: 300px; float: right; display: inline-block;
	padding:0 10px;
}
.section {margin:0}

h1,h2,h3,h4,h5,h6 {font-family: 'Baloo 2', 'Playfair Display', serif; font-weight: 600; }

/* ------------- HEADER ------------- */
header {text-align:center; padding-top: 90px;}
.Header h1 {
	font-size: 44px;
	color: var(--cp-ink);
	margin-bottom:0;
	font-weight:800;
}
.Header h1 a, .Header h1 a:hover {color: var(--cp-ink)}
.Header .description {font-family: 'Poppins', sans-serif; font-size: 13px; color: var(--cp-muted); font-style: normal;}
#Header1 #header-inner img {
	margin: 10px auto;
	max-width: 320px !important;
	text-align: center;
}
/* ------------- TOP MENU ------------- */
body .navbar {display: none;}
#topmenuwrap {
	width: 100%;
	padding: 0;
	margin: 0 auto;
	text-transform: uppercase;
	text-align: center;
	letter-spacing:1px;
	z-index: 10;
	position: fixed;
	top:6px;
	font-family: 'Poppins', sans-serif;
	background: #FFFFFF;
	box-shadow:0 2px 14px rgba(34,30,27,0.06);
}
.topwrap {
	width: 1140px;
	margin:0 auto;
	padding: 0;
	line-height: 50px;
}
#topmenuwrap .widget, .topwrap .section {margin:0}
#topmenuwrap .tabs-inner {padding: 0}


/* -- new menu -- */
#TOP-MENU {
	font: inherit;
	text-transform: uppercase;
	visibility:hidden;
	display:inline-block;
	font-size: 11px;
	font-weight:600;
	margin:0 10px;
}

#TOP-MENU .widget h2.title, #TOP-MENU .widget h2 {display: none}

.topmenu h3 {
	display: none;
}

.topmenu .menu {
    width: 100%;
    padding: 0;
    box-sizing: border-box;
    text-align: left;
    z-index: 10;
}

.topmenu .menu ul,
.topmenu .menu li{
	padding: 0;
}

.widget.PageList li {
	display: inline-block;
}

.PageList li a {
	color: var(--cp-ink);
	padding: 6px 14px;
	border-radius:999px;
	transition:.2s;
}
.PageList li a:hover {
	color: #fff;
	background: var(--cp-red);
}

/*first level*/
.topmenu .menu > ul {
	width: 100%;
	position: relative;
	display: inline-block;
	text-align: center;
}


.topmenu .menu ul li {
	padding: 0;
	position: relative;
	line-height: 45px;
	margin-right: 6px;
	letter-spacing: 1px;
	list-style: none;
}

/* buka submenu dg hover */
#TOP-MENU .widget li.sharewidth:hover .level-two,
#TOP-MENU .widget .level-two li.sharewidth:hover .level-three {
	display: block;
}

/*Drop Down Toggle Links*/
.menu .fa-angle-down,
.menu .fa-angle-right {
	display: none;
}

.menu .fa{
	border: 1px solid var(--cp-ink);
	border-radius: 2px;
	padding: 3px 0px;
	color: var(--cp-ink);
	margin: 0 10px;
}

.menu fa a{
	font-size: 0;
	padding: 0 !important;
}

.menu fa a:hover,
.menu fa a:focus{
	cursor: pointer;
}
.menu .nav .parent.sharewidth > a:after {
	content : ' \f107';
	font-family:'Font Awesome 5 Free'!important;
	font-weight: 900;
}

/* Second Level */
.menu .level-two{
	display: none;
	position: absolute;
	background: #fff;
	box-shadow: var(--cp-shadow);
	border-radius: 12px;
	top: 100%;
	left: 50%;
	width: 190px;
	z-index: 999;
	margin : 8px 0 0 -95px;
	overflow:hidden;
}

.menu .level-two > li{
	display: block;
	background: #fff;
	padding: 0;
	transition: .3s all ease;
	position: relative;
	white-space: nowrap;
	width: 100%;
	line-height: normal!important;
}

.menu .level-two > li a {
	width: 100%;
	display: block;
	padding: 12px;
	box-sizing: border-box;
	text-align: center;
}
.menu .level-two > li a:hover{background: var(--cp-yellow);}

/* List Items with Sub Menus*/
.menu .sharewidth > a {
	display: inline-block;
	width: auto;
}

.menu .child-item.sharewidth > a:after {
	content : ' \f105';
	font-family:'Font Awesome 5 Free'!important;
	font-weight: 900;
}

.menu .level-three{
	display: none;
	position: absolute;
	left: 100%;
	top: -1px;
	background: #fff;
	width: 175px;
	border-radius: 12px;
	box-shadow: var(--cp-shadow);
}

.menu .level-three li {
	display: block;
	background: transparent;
	padding: 0;
	transition: .3s all ease;
	position: relative;
	white-space: nowrap;
	width: 100%;
	line-height: normal!important;
}

.menu .level-three li a {
	padding: 10px;
}

#nav-trigger {
	position: absolute;
	left: 30px;
	top: 25px;
	display: none;
	z-index:1000;
	width: 100%;
}
#nav-trigger span {
	display: block;
	cursor: pointer;
	text-transform: uppercase;
	padding: 0;
	line-height: 40px;
	font-size: 14px;
	width: 100%;
	text-align: left;
	color: var(--cp-ink);
	font-size: 14px;
	line-height:40px;
}
#nav-mobile {
	position: relative;
	display: none;
}
.searchwrap {
	border :none;
    width: 100%;
	overflow: hidden;
	margin-left: 0;
	border:1px solid var(--cp-line);
	border-radius:999px;
}
#search-box {
    color: #444;
    border: none;
    cursor: pointer;
    margin-left: 12px;
    padding: 0;
    width: 240px;
    font-size: 11px;
	line-height: 40px;
	background: transparent;
	float:left;
	text-transform: uppercase;
}
.btnsearch {
	width: 25px;
	float: left;
	font-size: 16px;
    cursor: pointer;
    padding: 0;
    margin: 0;
    color: var(--cp-ink);
	background: none;
	border: none;
	line-height: 40px;
}
.btnsearch:hover {color: var(--cp-red);}

/* ------------- SOSMED ------------- */
#SOCIAL-MEDIA {
	float: none;
	display:inline-block;
	padding: 0;
}
#SOCIAL-MEDIA h2 {display: none}

#socmedicons {
	font-size: 15px;
	margin: 0;
	padding: 0;
	text-align: center;
}
#socmedicons a {
	color: #000;
	display: inline-block;
	padding: 0 5px;
}
#socmedicons a:hover {color: var(--cp-red);}

#topmenuwrap #socmedicons a:hover {color:var(--cp-red);}
#topmenuwrap #socmedicons {position:relative; z-index:9999;}
aside #socmedicons {z-index:1}

/* ------------- FEATURED POST WIDGET ------------- */
#featwrap {position: relative; width: 1140px; margin:55px auto 30px; overflow: hidden}
.feat-img-wrap {position: relative;}

#featwrap .widget {
	float: left;
	width: 258px;
	margin:0 10px;
}
#featwrap .widget.Image img {
	width:100%; height: 210px; object-fit: cover;
	border-radius: var(--cp-radius);
	box-shadow: var(--cp-shadow);
	opacity:1;
	transition:.2s;
}
#featwrap .widget.Image img:hover {transform:translateY(-4px); opacity:0.92}
#featwrap .widget.Image > a{width: 140px; position: absolute; left: 50%; bottom: 14px; z-index: 9;}
#featwrap .widget.Image > a:hover {color: #000}
#featwrap .widget.Image h2 {
	background: #fff; text-align: center; padding:8px 14px; position: relative; left: -50%;
	font-size: 11px; font-family: 'Poppins', sans-serif; font-weight:600; text-transform: uppercase; letter-spacing:1px;
	border-radius:999px; box-shadow: var(--cp-shadow);
}
#featwrap .widget-content {position: relative;}
#featwrap .widget.Image .caption {display: none}

/* ------------- ASIDE / SIDEBAR CARDS ------------- */
aside {text-align: center}
aside .widget {
	background: var(--cp-card);
	border-radius: var(--cp-radius);
	box-shadow: var(--cp-shadow);
	padding: 20px;
	margin-bottom: 24px;
}
aside .widget-content {
	font-size: 12px;
	line-height: 1.6em;
}
aside .widget h2 {
	font-family: 'Baloo 2', sans-serif;
	font-size: 13px;
	letter-spacing: 0.5px;
	text-transform: uppercase;
    color: var(--cp-ink);
    text-align: center;
    display: block;
    margin-bottom: 14px;
    padding: 0 0 10px;
	font-weight: 700;
	border-bottom: 2px solid var(--cp-yellow);
}
aside .widget h2 span { background-color: transparent; position: relative; padding:0; }
aside .widget h2:before { display:none; }
#ArchiveList .toggle {
	position: absolute;
	width:100%;
	z-index:10;
	height: 22px;
	left:0;
}
#ArchiveList .zippy {display: none}
.BlogArchive #ArchiveList ul {margin-bottom: 5px;}
.BlogArchive #ArchiveList ul li { font-size: 11px; text-align: center; text-transform: uppercase; padding-left:0}
#ArchiveList li.archivedate.expanded:before { content:"\f107"; font-family:fontawesome; }
#ArchiveList li.archivedate.collapsed:before { content:"\f105"; font-family:fontawesome; }
#ArchiveList ul ul li.archivedate.collapsed:before,
#ArchiveList ul ul li.archivedate.expanded:before {content:"";}
#ArchiveList li.archivedate .post-count {display: none}
#ArchiveList li.archivedate ul li .post-count{display: inline}
#ArchiveList a.post-count-link  {display: inline}
.BlogArchive #ArchiveList ul ul li {padding:10px 0 0}

aside .Label ul {display:flex; flex-wrap:wrap; gap:8px; justify-content:center;}
aside .Label ul li {
    padding: 0; margin: 0;
	font-family: 'Poppins', sans-serif;
	font-size: 11px;
}
aside .Label ul li a{
	display:inline-block;
	padding:6px 14px;
	border-radius:999px;
	background: #FFF3D6;
	color: var(--cp-ink);
	font-weight:600;
}
aside .Label ul li a:hover{background: var(--cp-yellow);}

input.gsc-input {
	background-color: #F6F1E7 !important;
	border: medium none !important;
	font-family: 'Poppins', sans-serif;
	font-size: 11px;
	letter-spacing: 1px;
	padding: 8px 12px !important;
	border-radius:999px 0 0 999px !important;
}
input.gsc-search-button {
	background-color: var(--cp-ink);
	border: medium none;
	color: #fff;
	font-family: 'Poppins', sans-serif;
	font-size: 11px;
	letter-spacing: 1px;
	text-transform: uppercase;
	padding: 8px 14px;
	border-radius:0 999px 999px 0;
}
#ArchiveList select {
	background-color: #F6F1E7 !important;
	border: medium none !important;
	font-family: 'Poppins', sans-serif;
	font-size: 11px;
	letter-spacing: 1px;
	padding: 8px !important;
	border-radius:999px;
	text-align: center;
}
aside .widget.HTML .widget-content { font-size: 12px; line-height: 1.9em; }
aside .widget.HTML .widget-content a {color: var(--cp-red);}
aside .widget.HTML .widget-content a:hover {color: var(--cp-ink);}

.FollowByEmail .follow-by-email-inner .follow-by-email-address {
    border: 1px solid var(--cp-line);
    color: #646464;
	font-family: 'Poppins', sans-serif;
	font-size: 11px;
    line-height: 34px;
    width: 100%;
    text-align: center;
    padding: 3px 12px;
    margin: 0 0 10px;
    letter-spacing: 0.5px;
	border-radius:999px;
}
.FollowByEmail .follow-by-email-inner .follow-by-email-submit {
    background: var(--cp-red);
    border: none;
    color: #ffffff;
    cursor: pointer;
    height: 36px;
    margin: 0;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 1px;
    transition: all 0.3s ease 0s;
    font-family: 'Poppins', sans-serif;
	font-weight:600;
	font-size: 11px;
    width: 100%;
	border-radius:999px;
}
.FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover { background: var(--cp-ink); }

/* ------------- ABOUT ME WIDGET ------------- */
.sidebar-wrap .widget.Image img {width: 100%; height: auto; border-radius: var(--cp-radius);}
.widget .widget-item-control a img {width:18px!important; height: 18px;}
aside .widget.Image .caption {margin-top: 10px; display: block; font-style: normal; font-size: 11px; line-height: 1.8em;}

/* ------------- Popular Posts ------------- */
.PopularPosts li {position: relative; text-align:left; margin-bottom:14px; padding-bottom:14px; border-bottom:1px solid var(--cp-line);}
.PopularPosts li:last-child{border-bottom:none; margin-bottom:0; padding-bottom:0;}
.PopularPosts img {width: 100%; height: 130px; object-fit: cover; border-radius:12px;}
.PopularPosts .item-thumbnail { margin:0 0 10px; padding:0; position:relative!important; left:0; width:100%; height:auto; display:block; }
.PopularPosts .item-thumbnail a { width: 100%; height: 130px; display:block; overflow: hidden; border-radius:12px; position: relative; opacity: 1; transition: all 0.2s ease-in-out; }
.PopularPosts .item-thumbnail a:hover {opacity: 0.85}
.PopularPosts .item-content, .PopularPosts .item-thumbnail {position: relative}
.item-snippet {display: none}
.PopularPosts .item-title a {
    background-color: transparent;
    width: 100%;
    display: block;
    margin: 0 auto;
    padding: 0;
	font-family: 'Poppins', sans-serif; font-size: 12.5px; font-weight:600; font-style: normal;
	text-align: left;
    }
.PopularPosts .item-title a {color: var(--cp-ink);}
.PopularPosts .item-title a:hover {color: var(--cp-red);}

/* ------------- POSTINGAN HOME (card grid) ------------- */
.blog-posts.hfeed{display:flex; flex-wrap:wrap; gap:26px;}
.post-wrap.date-outer{width:100%;}
.date-posts{display:flex; flex-wrap:wrap; gap:26px;}
.post-outer{
	width: calc(50% - 13px);
	background: var(--cp-card);
	border-radius: var(--cp-radius);
	box-shadow: var(--cp-shadow);
	overflow:hidden;
	transition:.2s;
}
.post-outer:hover{transform:translateY(-4px);}
.post {margin-bottom: 0; line-height: 1.8em;}
.post-body .posts-thumb {}
.post-thumbb {display: block; margin:0 0 14px; padding:0}
.post-thumbb a {text-align: center; display: block; border-radius:0; overflow:hidden;}
.post-thumbb img{width:100%; height:210px; object-fit:cover;}
.post-header {
	text-align: left;
	padding: 18px 20px 0;
}
.post-header .post-title {line-height: 1.3;}
.post-body .post-header a {color: var(--cp-ink); border-bottom:none;}
.post-body .post-header a:hover {color: var(--cp-red)}
.post-labels a {
	color: var(--cp-ink) !important;
	background:#FFF3D6;
	padding:4px 10px;
	border-radius:999px;
	font-weight:600;
	font-size:10px;
}
.hasilpot {text-align: left; padding: 0 20px 20px;}
.hasilpot .readmore {display: block; margin: 15px 0 0;}
.hasilpot .readmore a{
	padding: 0.6em 1.4em;
	font-family: 'Poppins', sans-serif;
	font-size: 10px;
	font-weight:600;
	letter-spacing: 1px;
	color: #ffffff;
	width: auto;
	margin: 0;
	text-align: center;
	display: inline-block;
	text-transform: uppercase;
	background-color: var(--cp-red);
	border-radius:999px;
	border:none;
}
.hasilpot .readmore a:hover { background-color: var(--cp-ink); }
.perintilan-header {display: block; margin:0 0 10px; text-align: left}
.post-header .post-comment-link {display: none}

/* ------------- POSTINGAN (single post) ------------- */
b, strong {font-weight: 700}
i {font-style: italic}
.post-wrap {margin:0;}
.date-header {display:none;}
.post-title {
	font-family: 'Baloo 2', sans-serif;
	text-transform: none;
	font-weight: 700;
	font-size: 26px;
	font-style: normal;
	letter-spacing:0;
	margin: 8px 0;
	padding:0;
	text-align: left
}
.post-title a {color: var(--cp-ink);}
.post-title a:hover {color: var(--cp-red);}
.post-body img, #Header1_headerimg, .widget.Image { max-width: 100%; height: auto; border-radius: 12px; }
.post-header {display: block; width: 100%}
.post-location, .post-labels, .post-header {
	font-size: 11px;
	letter-spacing: 0.5px;
	display:inline-block;
	font-style: normal;
	margin-left: 0;
	margin-right:8px;
}
.post-labels, .post-header { padding-left: 0px; margin-left: 0px; }
.post-timestamp {display: none}
.post-body {margin-top: 0; padding: 0 20px 20px;}
.post-body a {color: var(--cp-red); border-bottom: 2px solid var(--cp-yellow);}
.post-body a:hover {color: var(--cp-ink);}
.contains-image {border-bottom:none!important;}
td.tr-caption {font-style: italic;}
.post-sharing { float: none; text-align: left; position: relative; border-bottom:none; line-height: normal; height:auto; margin-top: 20px; }
.psw { background: transparent; width: auto; margin: 0!important; padding: 0; }
.post-sharing a {
    display: inline-block;
    padding: 10px;
    text-align:center;
    font-size: 13px;
    margin: 0 4px 0 0;
    color: var(--cp-ink);
	width: 14px; height: 14px;
	border:1px solid var(--cp-line);
	border-radius: 100px;
    }
.sharedis a:hover {color: #fff; background-color: var(--cp-red); border-color: var(--cp-red);}
#blog-pager {margin:3em 0}
.blog-pager {
	font-family: 'Poppins', sans-serif;
    font-size: 11px;
    color: var(--cp-ink);
    text-align: center;
    display: block;
    margin-bottom: 10px;
    padding: 5px 0;
}
.blog-pager #blog-pager-newer-link {width: 45%; overflow: hidden;text-align: left;}
.blog-pager .blog-pager-newer-link i {float: left; width: 20px; font-size: 20px; padding-top: 8px;}
.blog-pager .blog-pager-newer-link span {float: left; text-align: left;}

.blog-pager #blog-pager-older-link {width: 45%; overflow: hidden; text-align: right;}
.blog-pager .blog-pager-older-link i {float: right; width: 20px; font-size: 20px; padding-top: 8px;}
.blog-pager .blog-pager-older-link span {float: right; text-align: right;}

.blogpager1 {text-transform: uppercase!important; font-weight: bold;}
.blog-pager a:hover {color: var(--cp-red)}
.blog-pager-newer-title, .blog-pager-older-title {
	text-transform: normal!important;
	font-family: 'Poppins', sans-serif;
	font-size: 11px!important;
	letter-spacing:0.5px!important;
}

.Attribution, .blog-feeds, .home-link, .post-feeds {display: none}

.status-msg-border {border: none}
.status-msg-bg {opacity:1; background-color:#fff}
.status-msg-wrap {font-size: 14px; text-transform: uppercase; letter-spacing: 2px; font-weight: bold;}
.status-msg-body {position: relative}
.status-msg-hidden {display: none}
.post-body ol, .post-body ul {padding:0 2.5em; margin: 10px 0;}
.post-body ol li {list-style: auto!important}
.post-body ul li {list-style: disc}
.widget.Blog ol li {list-style: decimal!important}
.post blockquote {
    background: #FFF9EC;
    border: none;
	border-left: 4px solid var(--cp-yellow);
    margin: 20px 0;
    padding: 16px 24px;
	border-radius: 0 12px 12px 0;
}

/* ------------- RELATED ------------- */
#related-posts {margin:35px 0 0; padding: 0 20px 20px;}
#related-posts h4 {
display: block;
text-align: left;
	font-weight: 700;
	font-family: 'Baloo 2', sans-serif;
	font-size: 15px;
	letter-spacing: 0;
	font-style: normal;
	margin-bottom: 14px;
}
.related-posts-container{ margin:0; }
.related-posts-container h4{ margin-bottom:14px; }
.related-posts-container ul,.related-posts-container ul li{ text-align:left; list-style: none; margin: 0; padding: 0; }
.related-posts-container ul li a{ text-transform:none !important; outline: 0; }
.related-snippets{ margin-top:5px; }
li.related-post-item{
	margin:0 3% 3% 0 !important;
	width:22.7%;
	float:left;
	list-style:none;
	position:relative;
}
li.related-post-item:last-child{ margin:0 0 2% !important; }
.related-thumb-large{ width:100%; height:auto; border:none; margin:0px auto 10px; padding:0 !important; border-radius:12px;}
.related-title{font-family:'Poppins',sans-serif; font-weight:600; font-size:12px;}
.related-date{ margin-top:5px; font-size: 10px; color: var(--cp-muted); }

/* ------------- COMMENTS ------------- */
#comments {margin-top: 20px; padding:0 20px 20px;}
#comments h4 {
	padding: 10px 0;
	text-align: left;
	font-family: 'Baloo 2', sans-serif;
	font-size: 15px;
}
#comments > h4 {border-top: 1px solid var(--cp-line); border-bottom: none;}
.comments .comments-content .datetime, .comments .continue a {
    margin: 5px 0;
    font-size: 9px;
    text-transform: uppercase;
    display: block;
	font-family: 'Poppins', sans-serif;
}
.comments .continue a {font-size: 12px;}
.comments .comments-content .comment-content {margin:15px 0}
.comment-actions  {font-family: 'Poppins', sans-serif;  font-size: 9px; text-transform: uppercase;}
.comments ol {list-style: none!important}
.comments ol li, .widget.Blog .comments ol li {list-style: none!important}

/* ------------- FOOTER ------------- */
#back-top {
    position: fixed;
    bottom: 20px;
    right : 20px;
    z-index: 9999;
    font-size: 20px;
    }
#back-top a {
    width: 46px; height: 46px;
    display: flex; align-items:center; justify-content:center;
    text-decoration: none;
	background: var(--cp-ink);
	color:#fff;
	border-radius:50%;
	box-shadow: var(--cp-shadow);
    -webkit-transition: .3s;
    transition: .3s;
    }
#back-top a:hover{background: var(--cp-red);}
#skyfooter {
	width:100%;
	margin:0 auto;
	padding:20px 0 40px;
	text-align: center;
	font-family: 'Poppins', sans-serif;
	font-size: 10px;
	letter-spacing:0.5px;
	color: var(--cp-muted);
	text-transform: uppercase;
}
#skyfooter a {color: var(--cp-muted);}
#skyfooter a:hover {color: var(--cp-red);}

/* ------------- INSTAGRAM / FOOTER SECTION ------------- */
footer {background:#fff; margin-top:60px; border-top:1px solid var(--cp-line);}
footer .widget {margin:0}
#footer-insta {margin-top: 50px; margin-bottom: 10px; padding: 0 20px;}
#footer-insta h2 {
	font-family: 'Baloo 2', sans-serif;
    font-size: 15px;
    letter-spacing: 0;
    text-transform: none;
    color: var(--cp-ink);
    text-align: center;
    display: block;
    margin-bottom: 20px;
    padding: 5px 0;
    font-weight: 700;
}
.blog-feeds, .post-feeds {display: none}
#instagram-feed a img {opacity: 1}
#instagram-feed a img:hover {opacity: 0.8}

head.script:
//
function removeHtmlTag(strx,chop){
if(strx.indexOf("<")!=-1)
{
var s = strx.split("<");
for(var i=0;i<s.length;i++){
if(s[i].indexOf(">")!=-1){
s[i] = s[i].substring(s[i].indexOf(">")+1,s[i].length);
}
}
strx = s.join("");
}
chop = (chop < strx.length-1) ? chop : strx.length-2;
while(strx.charAt(chop-1)!=' ' && strx.indexOf(' ',chop)!=-1) chop++;
strx = strx.substring(0,chop-1);
return strx+'...';
}
function createSummaryAndThumb(pID, pURL, pTITLE){
var div = document.getElementById(pID);
var summ = posts_no_thumb_sum;
var summary = '<div class="post-summ">' + removeHtmlTag(div.innerHTML,summ) + '</div>';
div.innerHTML = summary;
}
//

//
$(function() {
    var one_level_list_element = $('#TOP-MENU .PageList ul'),
        menu_name = 'Menu',
        menu_wrapper_class = 'menu',
        parent_item_class = 'parent',
        child_item_class = 'child-item',
        grandchild_item_class = 'grandchild-item',
        children_wrapper_class = 'level-two',
        grandchildren_wrapper_class = 'level-three';

    var grandchild = $('li a:contains("__")'),
        child = $('li a:contains("_")');

    if (one_level_list_element.attr('class') == undefined) {
        one_level_list_element.addClass('nav');
        var ul_wrapper = 'nav';
    } else {
        var ul_wrapper = one_level_list_element.attr('class');
    }

    child.parent().addClass(child_item_class);

    var citem = $('.' + child_item_class);
    for (var i = 0; i < citem.length;) {
        i += citem.eq(i).nextUntil(':not(.' + child_item_class + ')').andSelf().wrapAll('<ul></ul>').length;
    }
    citem.parent().addClass(children_wrapper_class);

    grandchild.parent().addClass(grandchild_item_class);

    var gitem = $('.' + grandchild_item_class);
    for (var i = 0; i < gitem.length;) {
        i += gitem.eq(i).nextUntil(':not(.' + grandchild_item_class + ')').andSelf().wrapAll('<ul></ul>').length;
    }
    gitem.parent().addClass(grandchildren_wrapper_class);

    $('.' + ul_wrapper + ' > li').addClass(parent_item_class);

    $('.' + ul_wrapper + ' a').each(function() {
        $(this).text($(this).text().replace(/_/g, ' '));
    });

    $('.' + children_wrapper_class + ' > .' + child_item_class).each(function() {
        if ($(this).next().is('.' + grandchildren_wrapper_class)) {
            $(this).next().appendTo($(this));
        }
    });

    $('.' + ul_wrapper + ' > .' + parent_item_class).each(function() {
        if ($(this).next().is('.' + children_wrapper_class)) {
            $(this).next().appendTo($(this));
        }
    });

    $('.' + ul_wrapper).wrap('<div class="' + menu_wrapper_class + '"></div>');

    $('.' + children_wrapper_class).before('<i class="fas fa-fw fa-angle-down"></i>');
    $('.' + grandchildren_wrapper_class).before('<i class="fas fa-fw fa-angle-right"></i>');

    $('.fa-angle-down').click(function () {
		if ( $(this).siblings('.'+children_wrapper_class).is(':hidden') ) {
		$('.'+menu_wrapper_class+' .'+children_wrapper_class).slideUp();
		$(this).siblings('.'+children_wrapper_class).slideToggle();
		}
		else {
		$(this).siblings('.'+children_wrapper_class).slideUp();
		}
	});

	if ($('li > .fa-angle-down').length > 0){
		$('li > .fa-angle-down').parent().addClass('sharewidth');
	}

    $('.fa-angle-right').click(function() {
        if ($(this).siblings('.' + grandchildren_wrapper_class).is(':hidden')) {
            $('.' + menu_wrapper_class + ' .' + grandchildren_wrapper_class).slideUp();
            $(this).siblings('.' + grandchildren_wrapper_class).slideToggle();
        } else {
            $(this).siblings('.' + grandchildren_wrapper_class).slideUp();
        }
    });

    $('.navtoggle').click(function() {
        $('.' + menu_wrapper_class).toggleClass('active');
        $('.' + children_wrapper_class + ' .fa').toggleClass('fa-angle-right, fa-angle-down');
    });

    if ($('li > .fa-angle-right').length > 0) {
        $('li > .fa-angle-right').parent().addClass('sharewidth');
    }

    var menuheight = $('.' + menu_wrapper_class).outerHeight();
});
